"""Redis-backed cache keyed by approximate nearest embedding match."""

from __future__ import annotations

import json
from typing import Any

import numpy as np
import redis.asyncio as redis

from app.core.config import CacheConfig, YamlAppConfig
from app.core.logging import get_logger
from app.ingestion.embedders import EmbedderPlugin

log = get_logger(__name__)


class SemanticCache:
    def __init__(self, yaml_cfg: YamlAppConfig, redis_client: redis.Redis, embedder: EmbedderPlugin) -> None:
        self._cfg: CacheConfig = yaml_cfg.cache
        self._r = redis_client
        self._embedder = embedder
        self._prefix = "semcache:"

    def _key_main(self, query_hash: str) -> str:
        return f"{self._prefix}{query_hash}"

    @staticmethod
    def _cosine(a: list[float], b: list[float]) -> float:
        va = np.array(a, dtype=np.float64)
        vb = np.array(b, dtype=np.float64)
        n = np.linalg.norm(va) * np.linalg.norm(vb)
        if n == 0:
            return 0.0
        return float(np.dot(va, vb) / n)

    # Generated by GitHub Copilot - Nov-08-2026
    async def lookup(self, query: str, collection_id: str | None = None) -> dict[str, Any] | None:
        """Return the most similar cached answer for the same collection, or None.

        Entries from other collections (or legacy entries without collection info) are skipped
        so answers never leak across collection filters.
        """
        qvec = self._embedder.embed(query)
        scope = collection_id or ""
        best_sim = self._cfg.similarity_threshold
        best: dict[str, Any] | None = None
        async for k in self._r.scan_iter(match=f"{self._prefix}*", count=100):
            key_s = k.decode() if isinstance(k, (bytes, bytearray)) else str(k)
            raw = await self._r.get(key_s)
            if not raw:
                continue
            try:
                payload = json.loads(raw)
            except json.JSONDecodeError:
                continue
            ev = payload.get("embedding")
            if not ev or payload.get("collection_id") != scope:
                continue
            sim = self._cosine(qvec, ev)
            if sim >= best_sim:
                best_sim, best = sim, payload.get("value")
        return best

    # Generated by GitHub Copilot - Nov-08-2026
    async def store(self, query: str, value: dict[str, Any], collection_id: str | None = None) -> None:
        """Cache an answer scoped to the collection it was generated for."""
        qvec = self._embedder.embed(query)
        scope = collection_id or ""
        h = str(abs(hash((query, scope))) % (10**12))
        key = self._key_main(h)
        payload = json.dumps(
            {"embedding": qvec, "value": value, "query": query[:500], "collection_id": scope}
        )
        await self._r.setex(key, self._cfg.ttl_seconds, payload)

    async def clear_prefix(self) -> int:
        n = 0
        async for k in self._r.scan_iter(match=f"{self._prefix}*", count=200):
            key_s = k.decode() if isinstance(k, (bytes, bytearray)) else str(k)
            await self._r.delete(key_s)
            n += 1
        return n

    # Generated by GitHub Copilot - Nov-08-2026
    async def clear_if_enabled(self) -> int | None:
        """Drop cached answers after documents change; returns None when caching is off.

        Errors are logged and swallowed so a Redis outage never fails an upload/delete/reindex.
        """
        if self._cfg.backend != "redis":
            return None
        try:
            return await self.clear_prefix()
        except Exception as e:
            log.warning("semantic_cache_clear_failed", error=str(e))
            return None
